// buildStackSnippet renders a runnable stackstac/pystac-client Python snippet
// for the given search, embedding the bbox, datetime, and bands.
func buildStackSnippet(baseURL, collection string, bbox []float64, datetime string, bands []string, itemCount int) string {
	bandList := "[\"" + strings.Join(bands, "\", \"") + "\"]"
	bboxLiteral := "None"
	if len(bbox) > 0 {
		parts := make([]string, len(bbox))
		for i, v := range bbox {
			parts[i] = fmt.Sprintf("%g", v)
		}
		bboxLiteral = "[" + strings.Join(parts, ", ") + "]"
	}
	datetimeLiteral := "None"
	if datetime != "" {
		datetimeLiteral = "\"" + datetime + "\""
	}
	return fmt.Sprintf(`# %d matching items. Requires: pip install pystac-client stackstac
import stackstac
from pystac_client import Client

client = Client.open("%s")
search = client.search(
    collections=["%s"],
    bbox=%s,
    datetime=%s,
)
items = list(search.items())
stack = stackstac.stack(items, assets=%s)
print(stack)`, itemCount, baseURL, collection, bboxLiteral, datetimeLiteral, bandList)
}
